'use client';

import { ScrollArea as ScrollAreaPrimitive } from '@base-ui/react/scroll-area';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

function ScrollArea({ className, children, ...props }: ScrollAreaPrimitive.Root.Props) {
  return (
    <ScrollAreaPrimitive.Root
      className={(state) => cn('relative', typeof className === 'function' ? className(state) : className)}
      data-slot="scroll-area"
      {...props}
    >
      <ScrollAreaPrimitive.Viewport
        className="size-full outline-none focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-1 motion-reduce:transition-none"
        data-slot="scroll-area-viewport"
      >
        {children}
      </ScrollAreaPrimitive.Viewport>
      <ScrollBar />
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  );
}
function ScrollBar({ className, orientation = 'vertical', ...props }: ScrollAreaPrimitive.Scrollbar.Props) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      className={(state) =>
        cn(
          'flex touch-none p-px transition-colors select-none data-horizontal:h-2.5 data-horizontal:flex-col data-horizontal:border-t data-horizontal:border-t-transparent data-vertical:h-full data-vertical:w-2.5 data-vertical:border-l data-vertical:border-l-transparent',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-orientation={orientation}
      data-slot="scroll-area-scrollbar"
      orientation={orientation}
      {...props}
    >
      <ScrollAreaPrimitive.Thumb className="relative flex-1 rounded-full bg-border" data-slot="scroll-area-thumb" />
    </ScrollAreaPrimitive.Scrollbar>
  );
}

export { ScrollArea, ScrollBar };

import { cva } from 'class-variance-authority';
import { type ClassValue, clsx } from 'clsx';
import type React from 'react';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function wrapStringChild(
  child: React.ReactNode,
  Wrapper: React.ComponentType<{
    children: React.ReactNode;
    className?: string | undefined;
  }>,
  className?: string
): React.ReactNode {
  if (typeof child === 'string') {
    return <Wrapper className={className}>{child}</Wrapper>;
  }
  return child;
}

export interface SharedProps {
  testId?: string | undefined;
}

export interface PortalRootProps {
  defaultOpen?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  open?: boolean | undefined;
}

export type ModalRootProps = PortalRootProps & {
  modal?: boolean | undefined;
};

export interface FocusScopeContentProps {
  onCloseAutoFocus?: ((event: Event) => void) | undefined;
  onOpenAutoFocus?: ((event: Event) => void) | undefined;
}

export type PortalContentProps = FocusScopeContentProps & {
  container?: HTMLElement | undefined;
};

export type FixedPositionContentProps = PortalContentProps & {
  showOverlay?: boolean;
};

export type SemanticVariant = 'success' | 'info' | 'warning' | 'error' | 'disabled';
export type DotSize = 'xxs' | 'xs' | 'sm' | 'md' | 'lg';
export interface StackableProps {
  stacked?: boolean;
}

export const dotColorVariants = cva('', {
  defaultVariants: {
    variant: 'info',
  },
  variants: {
    variant: {
      disabled: 'bg-muted',
      error: 'bg-destructive',
      info: 'bg-primary',
      success: 'bg-primary',
      warning: 'bg-primary',
    },
  },
});

export const dotStackedVariants = cva('!border-background', {
  defaultVariants: {
    size: 'md',
  },
  variants: {
    size: {
      lg: 'border-2',
      md: 'border-2',
      sm: 'border',
      xs: 'border-2',
      xxs: 'border',
    },
  },
});
